static int sm5440_set_op_mode(struct sm5440_charger *sm5440, u8 op_mode)
{
	int ret;

	ret = sm5440_update_reg(sm5440, SM5440_REG_CNTL5, op_mode, 0x3, 2);

	return ret;
}

static int sm5440_set_ENHIZ(struct sm5440_charger *sm5440, bool vbus, bool chg_en)
{
	u8 enhiz = 0;   /* case : chg_on or chg_off & vbus_uvlo */

	if (vbus && !(chg_en))
		enhiz = 1;              /* case : chg_off & vbus_pok */

	dev_info(sm5440->dev, "%s: vbus=%d, chg_en=%d, enhiz=%d\n",
			__func__, vbus, chg_en, enhiz);
	sm5440_update_reg(sm5440, SM5440_REG_CNTL6, enhiz, 0x1, 7);

	return 0;
}

static int sm5440_set_charging_enable(struct i2c_client *i2c, bool enable)
{
	struct sm5440_charger *sm5440 = i2c_get_clientdata(i2c);

	sm5440_set_ENHIZ(sm5440, sm5440->vbus_in, enable);
	if (enable)
		sm5440_set_op_mode(sm5440, OP_MODE_CHG_ON);
	else
		sm5440_set_op_mode(sm5440, OP_MODE_CHG_OFF);

	sm5440_enable_wdt(sm5440, enable);
	sm5440_print_regmap(sm5440);

};

enum sm5440_wdt_tmr {
	WDT_TIMER_S_0P5     = 0x0,
	WDT_TIMER_S_1       = 0x1,
	WDT_TIMER_S_2       = 0x2,
	WDT_TIMER_S_4       = 0x3,
	WDT_TIMER_S_30      = 0x4,
	WDT_TIMER_S_60      = 0x5,
	WDT_TIMER_S_90      = 0x6,
	WDT_TIMER_S_120     = 0x7,
};

static int sm5440_pump_off(struct sm5440_direct *sm)
{
	return sm5440_update_bits(sm, SM5440_REG_CNTL5,
				  SM5440_CNTL5_OP_MODE_MASK, 0);
}

static int sm5440_pump_on(struct sm5440_direct *sm)
{
	int status3 = 0;
	int i;
	int ret;

	ret = sm5440_update_bits(sm, SM5440_REG_CNTL5,
				 SM5440_CNTL5_OP_MODE_MASK,
				 SM5440_CNTL5_CHG_ON);
	if (ret)
		return ret;

	/*
	 * VBUSPOK is set as soon as the pump starts pulling the bus down, which is
	 * well before the 100 ms this used to sleep unconditionally.  Poll for it
	 * instead, keeping the old worst case as the loop bound.
	 */
	for (i = 0; i < 5; i++) {
		msleep(20);
		status3 = i2c_smbus_read_byte_data(sm->client,
						   SM5440_REG_STATUS3);
		if (status3 < 0)
			return status3;
		if (status3 & SM5440_STATUS3_VBUSPOK)
			return 0;
	}

	return -ENOLINK;

ret = sm5440_wait_vbus_settled(sm, target_mv);
if (ret)
	goto restore;

ret = sm5440_update_bits(sm, SM5440_REG_CNTL1,
			 SM5440_CNTL1_WDT_EN,
			 SM5440_CNTL1_WDT_EN);
if (ret)
	goto restore;

ret = sm5440_pump_on(sm);
if (ret)
	goto restore;

sm->active = true;
sm->target_mv = target_mv;

static int _regmap_update_bits(struct regmap *map, unsigned int reg,
			       unsigned int mask, unsigned int val,
			       bool *change, bool force_write)
{
	int ret;
	unsigned int tmp, orig;

	if (change)
		*change = false;

	if (regmap_volatile(map, reg) && map->reg_update_bits) {
		if (map->cache_only)
			return -EBUSY;

		reg = regmap_reg_addr(map, reg);
		ret = map->reg_update_bits(map->bus_context, reg, mask, val);
		if (ret == 0 && change)
			*change = true;
	} else {
		ret = _regmap_read(map, reg, &orig);
		if (ret != 0)
			return ret;

		tmp = orig & ~mask;
		tmp |= val & mask;

		if (force_write || (tmp != orig) || map->force_write_field) {
			ret = _regmap_write(map, reg, tmp);
			if (ret == 0 && change)
				*change = true;
		}
	}
